GameAnalytics = {}

local ReportTimes = 0
---@type file
local LogFile
---@type EventConfig
local EventConfig = T(Global, "EventConfig")
---@type boolean
local ReportEngineEvent = true
---@type number
local ReportTimestamp = 0
---@type number
local SecondReportTimes = 0
---@type number
local EventId = 0
---@type uuid
local uuid = require "engine_base.util.uuid"

local function generateEventId()
    EventId = EventId + 1
    return uuid() .. "-" .. EventId
end

function GameAnalytics:init()
    EventConfig:init()
    uuid.randomseed(os.time() + HostApi.random("uuid", 1, 100000000))
    self.eventBlacklist = {}
    self:getEventBlacklist()
    LuaTimer:scheduleTimer(function()
        self:getEventBlacklist()
    end, 60 * 60 * 1000)
    local path
    local fileName
    if Platform.isWindow() then
        path = "GameAnalytics"
        fileName = tostring(os.time()) .. ".log"
    else
        local config = GameServer:getServerConfig()
        if config.gameEventLogDir and #config.gameEventLogDir > 0 then
            path = config.gameEventLogDir
        else
            path = "/home/app/bmg/log/game_event_log"
        end
        fileName = config.gameId .. ".log"
    end
    os.execute("mkdir " .. path)
    LogFile = io.open(path .. "/" .. fileName, "a")
end

function GameAnalytics:getEventBlacklist()
    WebService:getEngineEventBlacklist(function(data, code)
        if code == 1 then
            self.eventBlacklist = {}
            local commonData = data["common"]
            local gameData = data[BaseMain:getGameType()]
            if commonData ~= nil and next(commonData) then
                for _, v in pairs(commonData) do
                    self.eventBlacklist[v] = true
                end
            end
            if gameData ~= nil and next(gameData) then
                for _, v in pairs(gameData) do
                    self.eventBlacklist[v] = true
                end
            end
        else
            print("[Lua] GameAnalytics:getEventBlacklist error: code = ", code)
        end
    end)
end

function GameAnalytics:checkEventBlacklist(event)
    return self.eventBlacklist ~= nil and self.eventBlacklist[event] ~= nil
end

---As session is the concept of a user spending a period of time focused on a game.
---The user event acts like a session start. It should always be the
---first event in the first batch sent to the collectors and added each time a session starts.
---@param userId number userId [player userId]
function GameAnalytics:sessionStart(userId)
    if not ReportEngineEvent then
        return
    end
    GameAnalytics:newDesign(userId, "Login")
end

---Whenever a session is determined to be over the code should always attempt
---to add a session end event and submit all pending events immediately.
---Only one session end event per session should be activated.
---@param userId number userId [player userId]
---@param length number length [player game time, eg: 120 (second)]
function GameAnalytics:sessionEnd(userId, length)
    if not ReportEngineEvent then
        return
    end
    GameAnalytics:newDesign(userId, "Logout", { online_time = length })
end

function GameAnalytics:performanceReport(player)
    if not ReportEngineEvent then
        return
    end
    if not player.performance or not player.performance.fps or
            not player.performance.netPing or not player.performance.logicPing then
        return
    end
    self:newDesign(player.userId, "battle_fps", player.performance.fps)
    self:newDesign(player.userId, "battle_net_ping", player.performance.netPing)
    self:newDesign(player.userId, "battle_logic_ping", player.performance.logicPing)
end

local function checkEvent(event)
    if type(event) ~= "string" then
        return false
    end
    if tonumber(event) ~= nil then
        return false
    end

    return true
end

local function NewReportByMap(userId, event, eventMap, parentId)
    if not checkEvent(event) then
        LogUtil.logError("event is illegal , event = ", event)
        return
    end

    if not EventConfig:checkEventKey(event, eventMap) then
        return
    end
    eventMap.event = event
    if GMHelper:isGMOpen(userId) then
        local player = PlayerManager:getPlayerByUserId(userId)
        if player then
            player:sendPacket({
                pid = "AddEventToDialog",
                event_map = eventMap
            })
        end
    end
    eventMap.sdk = eventMap.sdk or "mods"
    eventMap.event_type = "game"
    eventMap.game_type = BaseMain:getGameType()
    eventMap.engine_version = EngineVersionSetting.getEngineVersion()
    eventMap.region_id = tostring(GameServer:getServerConfig().regionId)
    local info = GameAnalyticsCache:getClientInfo(userId)
    if info then
        for key, value in pairs(info) do
            eventMap[key] = value
        end
    end
    local curTime = os.time()
    if curTime ~= ReportTimestamp then
        SecondReportTimes = 0
        ReportTimestamp = curTime
    end
    eventMap.user_id = tostring(userId)
    eventMap.id = generateEventId()
    if SecondReportTimes < 10 then
        eventMap.event_time = ReportTimestamp .. "00" .. SecondReportTimes
    elseif SecondReportTimes < 100 then
        eventMap.event_time = ReportTimestamp .. "0" .. SecondReportTimes
    else
        eventMap.event_time = ReportTimestamp .. SecondReportTimes
    end
    if SecondReportTimes < 999 then
        SecondReportTimes = SecondReportTimes + 1
    end
    if parentId then
        eventMap.parent_id = tostring(parentId)
    end
    if LogFile then
        LogFile:write(json.encode(eventMap) .. "\n")
        LogFile:flush()
    else
        LogUtil.logError("new report file create fail")
    end

    ReportTimes = ReportTimes + 1
    return eventMap.id
end

---Every game is unique! Therefore it varies what information is needed to track
---for each game. Some needed events might not be covered by our other event types
---and the design event is available for creating a custom metric using an event id hierarchy.
---@param userId number userId [player userId]
---@param value number value [Optional value. float]
---@param parts table parts [eg {"BreakBlock", BlockId, ...}]
---eventId structure
---A 1-5 part event id.
---[part1]:[part2]:[part3]:[part4]:[part5]
---pattern:^[A-Za-z0-9\\s\\-_\\.\\(\\)\\!\\?]{1,64}(:[A-Za-z0-9\\s\\-_\\.\\(\\)\\!\\?]{1,64}){0,4}$
function GameAnalytics:design(userId, value, parts)

end

---@param userId number userId [player userId]
---@param event string event [event name]
---@param event_map table event_map [eg {key1 = value1,key2 = value2, ...}]
function GameAnalytics:newDesign(userId, event, event_map, parentId)
    if type(event_map) ~= "table" then
        event_map = {}
    end
    local attr = GameServer:getRoomManager():getUserAttrInfo(userId)
    if attr and attr.isRobot then
        return
    end

    if AIManager and AIManager["isAIByUserId"] and AIManager:isAIByUserId(userId) then
        return
    end

    if self:checkEventBlacklist(event) then
        return
    end

    return NewReportByMap(userId, event, event_map, parentId)
end

---上报购买物品事件
---@param player SBasePlayer
---@param uniqueId string 商品唯一Id
---@param coinId number 货币类型
---@param price number 商品价格
---@param reason number 购买原因
function GameAnalytics:reportExchangeItems(player, uniqueId, coinId, price, reason, goodsCount)
    if not ReportEngineEvent then
        return
    end
    if coinId == 1 then
        coinId = 0
    end
    local balance = player:getCurrencyBalance()
    local money = balance[coinId] or 0
    local event_map = {
        reason = reason or ExchangeItemReason.Shop,
        currency_balance_type = coinId,
        currency_balance_num = money,
        currency_change_type = coinId,
        currency_change_num = price,
        item_change_item_id2 = tostring(uniqueId),
        item_change_item_num = goodsCount or 1,
    }
    GameAnalytics:newDesign(player.userId, "ExchangeItems", event_map)
end

function GameAnalytics:reportCheatDetect(userId, type, reason)
    local event_map = {
        item_id = type,
    }
    GameAnalytics:newDesign(userId, "engine_cheat_detect", event_map)
end

function GameAnalytics:updateBlacklist(blacklist)
    if blacklist and type(blacklist) == "table" then
        print("update report blacklist")
        Blacklist = {}
        GameAnalytics.Blacklist = {}
        local commonList = {}
        commonList = blacklist["common"]
        if commonList and #commonList > 0 then
            for i = 1, #commonList do
                Blacklist[commonList[i]] = 1
            end
        end

        local gameEventList = blacklist[World.GameName]

        if gameEventList and #gameEventList > 0 then
            for i = 1, #gameEventList do
                Blacklist[gameEventList[i]] = 1
                print("add blacklist event: " .. gameEventList[i])
            end
        end

        GameAnalytics.Blacklist = Blacklist
    end
end

function GameAnalytics:isBlacklistEvent(event)
    if Blacklist[event] ~= nil then
        return true
    end
    return false
end

function GameAnalytics:disableEngineEvent()
    ReportEngineEvent = false
end

return GameAnalytics